draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // head
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.fill();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 30);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 10);
  ctx.lineTo(W/2 - 30 + 20 * Math.sin(t), H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 10);
  ctx.lineTo(W/2 + 30 + 20 * Math.sin(t), H/2 + 20);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20 + 10 * Math.sin(t), H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20 + 10 * Math.sin(t), H/2 + 80);
  ctx.stroke();

  // hands
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 30 + 20 * Math.sin(t), H/2 + 20, 5, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 30 + 20 * Math.sin(t), H/2 + 20, 5, 0, 2 * Math.PI);
  ctx.fill();

  // feet
  ctx.beginPath();
  ctx.arc(W/2 - 20 + 10 * Math.sin(t), H/2 + 80, 5, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 20 + 10 * Math.sin(t), H/2 + 80, 5, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
